-- =====================================================================
-- DPRE UCXX: import of the Lease Dashboard MASTER DATA REPORT (as at 31 Aug 2026)
-- 684 leases. Generated from the workbook; re-running skips leases already present
-- (matched on LeaseReferenceNumber). Run RE_Leases_Create.sql first.
-- CCA and Property Manager come from the SUMMARY OF LEASE PORTFOLIO tab; the MOA flag from the
-- MEMORANDUM OF AGREEMENT tab. LeaseClassification is mapped to the UCXX classes (original kept in
-- SourceClassification) until the BA confirms the mapping.
-- =====================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

DECLARE @DeptId INT = (SELECT TOP 1 Id FROM dbo.ApplicationEntities WHERE [Key] = 'ap_real_estate_development');
DECLARE @Now DATETIME = GETDATE();

IF OBJECT_ID('tempdb..#RE_LeaseImport') IS NOT NULL DROP TABLE #RE_LeaseImport;
SELECT TOP 0 [ContractReferenceNumber], [LeaseReferenceNumber], [SolarAccountNumber], [PropertyCode], [HigherLevelPropertyCode], [PhysicalBuildingNumberAndName], [InvoiceClarification], [PhysicalStreetAddress], [Cca], [LeaseClassification], [SourceClassification], [LeaseDetailsAndPurpose], [LeasedAreaSqm], [AgreementInPlace], [RecordStatus], [ArchibusInvoice], [IsMemorandumOfAgreement], [LeaseStartDate], [EscalationDate], [LeaseEndDate], [LeaseTerminationDate], [LeaseIndefinite], [TerminationNoticePeriodMonths], [Legal], [PortfolioManager], [PropertyManager], [CollectionManager], [EscalationAlertsRecipient], [FinancialOfficer], [VenusRentalAccountNumber], [DepositHeld], [ApplicantType], [RegistrationNumber], [VatRegistrationNumber], [TenantName], [TenantCode], [DomiciliumBuildingNumberAndName], [DomiciliumStreetAddress], [DomiciliumSuburb], [DomiciliumTown], [DomiciliumPostalCode], [AdditionalComments], [ContactType], [BillingContactName], [BillingContactSurname], [AuthorisedRepresentative], [BillingBuildingNumberAndName], [BillingStreetAddress], [BillingSuburb], [BillingTown], [BillingPostalCode], [BillingMobile1], [BillingMobile2], [BillingTelephone1], [BillingTelephone2], [BillingFax1], [BillingEmail1], [BillingEmail2], [LeaseContactName], [LeaseContactSurname], [LeaseContactMobile1], [LeaseContactMobile2], [LeaseContactTelephone1], [LeaseContactTelephone2], [LeaseContactFax1], [LeaseContactEmail1], [LeaseContactEmail2], [Source] INTO #RE_LeaseImport FROM dbo.RE_Leases;


SELECT i.[ContractReferenceNumber], i.[LeaseReferenceNumber], i.[SolarAccountNumber], i.[PropertyCode], i.[HigherLevelPropertyCode], i.[PhysicalBuildingNumberAndName], i.[InvoiceClarification], i.[PhysicalStreetAddress], i.[Cca], i.[LeaseClassification], i.[SourceClassification], i.[LeaseDetailsAndPurpose], i.[LeasedAreaSqm], i.[AgreementInPlace], i.[RecordStatus], i.[ArchibusInvoice], i.[IsMemorandumOfAgreement], i.[LeaseStartDate], i.[EscalationDate], i.[LeaseEndDate], i.[LeaseTerminationDate], i.[LeaseIndefinite], i.[TerminationNoticePeriodMonths], i.[Legal], i.[PortfolioManager], i.[PropertyManager], i.[CollectionManager], i.[EscalationAlertsRecipient], i.[FinancialOfficer], i.[VenusRentalAccountNumber], i.[DepositHeld], i.[ApplicantType], i.[RegistrationNumber], i.[VatRegistrationNumber], i.[TenantName], i.[TenantCode], i.[DomiciliumBuildingNumberAndName], i.[DomiciliumStreetAddress], i.[DomiciliumSuburb], i.[DomiciliumTown], i.[DomiciliumPostalCode], i.[AdditionalComments], i.[ContactType], i.[BillingContactName], i.[BillingContactSurname], i.[AuthorisedRepresentative], i.[BillingBuildingNumberAndName], i.[BillingStreetAddress], i.[BillingSuburb], i.[BillingTown], i.[BillingPostalCode], i.[BillingMobile1], i.[BillingMobile2], i.[BillingTelephone1], i.[BillingTelephone2], i.[BillingFax1], i.[BillingEmail1], i.[BillingEmail2], i.[LeaseContactName], i.[LeaseContactSurname], i.[LeaseContactMobile1], i.[LeaseContactMobile2], i.[LeaseContactTelephone1], i.[LeaseContactTelephone2], i.[LeaseContactFax1], i.[LeaseContactEmail1], i.[LeaseContactEmail2], i.[Source],
       (SELECT TOP 1 c.Id FROM dbo.CCCs c WHERE UPPER(LTRIM(RTRIM(c.CCCName))) = UPPER(i.Cca)),
       @DeptId, 1, 0, 0, @Now, @Now
FROM #RE_LeaseImport i
WHERE NOT EXISTS (SELECT 1 FROM dbo.RE_Leases l WHERE l.LeaseReferenceNumber = i.LeaseReferenceNumber AND l.IsDeleted = 0);

DECLARE @Inserted INT = @@ROWCOUNT;

-- Audit trail for the imported rows
SELECT 'Added', l.Id, l.[ContractReferenceNumber], l.[LeaseReferenceNumber], l.[SolarAccountNumber], l.[PropertyCode], l.[HigherLevelPropertyCode], l.[PhysicalBuildingNumberAndName], l.[InvoiceClarification], l.[PhysicalStreetAddress], l.[Cca], l.[LeaseClassification], l.[SourceClassification], l.[LeaseDetailsAndPurpose], l.[LeasedAreaSqm], l.[AgreementInPlace], l.[RecordStatus], l.[ArchibusInvoice], l.[IsMemorandumOfAgreement], l.[LeaseStartDate], l.[EscalationDate], l.[LeaseEndDate], l.[LeaseTerminationDate], l.[LeaseIndefinite], l.[TerminationNoticePeriodMonths], l.[Legal], l.[PortfolioManager], l.[PropertyManager], l.[CollectionManager], l.[EscalationAlertsRecipient], l.[FinancialOfficer], l.[VenusRentalAccountNumber], l.[DepositHeld], l.[ApplicantType], l.[RegistrationNumber], l.[VatRegistrationNumber], l.[TenantName], l.[TenantCode], l.[DomiciliumBuildingNumberAndName], l.[DomiciliumStreetAddress], l.[DomiciliumSuburb], l.[DomiciliumTown], l.[DomiciliumPostalCode], l.[AdditionalComments], l.[ContactType], l.[BillingContactName], l.[BillingContactSurname], l.[AuthorisedRepresentative], l.[BillingBuildingNumberAndName], l.[BillingStreetAddress], l.[BillingSuburb], l.[BillingTown], l.[BillingPostalCode], l.[BillingMobile1], l.[BillingMobile2], l.[BillingTelephone1], l.[BillingTelephone2], l.[BillingFax1], l.[BillingEmail1], l.[BillingEmail2], l.[LeaseContactName], l.[LeaseContactSurname], l.[LeaseContactMobile1], l.[LeaseContactMobile2], l.[LeaseContactTelephone1], l.[LeaseContactTelephone2], l.[LeaseContactFax1], l.[LeaseContactEmail1], l.[LeaseContactEmail2], l.[Source], l.CCCId, l.DepartmentId, l.IsActive, l.IsDeleted, l.IsLocked, l.CreatedDateTime, l.ModifiedDateTime
FROM dbo.RE_Leases l
WHERE l.Source = 'Import' AND l.CreatedDateTime = @Now;

COMMIT TRANSACTION;
DROP TABLE #RE_LeaseImport;

PRINT CONCAT('RE_Leases imported: ', @Inserted, ' (', 684 - @Inserted, ' already present and skipped)');
